function purchaseTankVehicleModel(level){level=normalizeTankUpgradeLevel(level);if(G.upgradeBusy)return {ok:false,reason:'busy'};const spec=tankVehicleSpec(level),p=ensureProgress();if(!p||!spec)return {ok:false,reason:'unavailable'};if(tankVehicleIsOwned(level))return equipTankVehicleModel(level);const before=currentCoinBalance();if(before<spec.cost){showToast('เหรียญไม่พอ','ต้องใช้ '+spec.cost.toLocaleString()+' เหรียญ เพื่อซื้อ TANK '+spec.name);renderGarage();return {ok:false,reason:'insufficient',required:spec.cost,balance:before};}G.upgradeBusy=true;const paid=spendTankUpgradeCoins(spec.cost);if(!paid.ok){G.upgradeBusy=false;renderGarage();return paid;}const oldOwned=sanitizeTankVehicleOwnedLevels(p.tankVehicleOwnedLevels),oldEquipped=normalizeTankUpgradeLevel(p.tankVehicleEquippedLevel||1);try{p.tankVehicleOwnedLevels=sanitizeTankVehicleOwnedLevels([...oldOwned,level]);p.tankVehicleEquippedLevel=level;if(G.player)applyTankVehicleModel(G.player,level);persist();G.garageVehicleSelection=level;showToast('ซื้อรถถังสำเร็จ',spec.name+' · ใช้ MAIN COINS '+spec.cost.toLocaleString());renderGarage();return {ok:true,level,cost:spec.cost,balance:currentCoinBalance(),owned:true,equipped:true};}catch(error){try{restoreMainCoinBalance(paid.before);p.tankVehicleOwnedLevels=oldOwned;p.tankVehicleEquippedLevel=oldEquipped;if(G.player)applyTankVehicleModel(G.player,oldEquipped);if(typeof saveState==='function')saveState();}catch(_){}return {ok:false,reason:'rollback',error};}finally{setTimeout(()=>{G.upgradeBusy=false;renderGarage();},220);}}














