function specialControlState(){
  if(!G.specialControls||typeof G.specialControls!=='object')G.specialControls={autoMove:0,targetLockMode:false,lockedTarget:null,scopeMode:false};
  const s=G.specialControls;
  if(typeof s.scopeMode!=='boolean')s.scopeMode=false;
  if(!Number.isFinite(Number(s.targetSelectedAt)))s.targetSelectedAt=0;
  if(!Number.isFinite(Number(s.targetFireDeadlineAt)))s.targetFireDeadlineAt=0;
  if(typeof s.forceHullForward!=='boolean')s.forceHullForward=false;
  if(!s.lastTargetTapAction||typeof s.lastTargetTapAction!=='object')s.lastTargetTapAction=null;
  return s;
}

function targetLockSameTarget(a,b){return !!a&&!!b&&String(a.kind||'')===String(b.kind||'')&&((a.ref&&b.ref&&a.ref===b.ref)||(String(a.id||'')!==''&&String(a.id||'')===String(b.id||'')));}
function rememberTargetTapAction(action,x,y,now=inputNow()){const s=specialControlState();s.lastTargetTapAction={action:String(action||''),x:Number(x)||0,y:Number(y)||0,at:Number(now)||0};return s.lastTargetTapAction;}
function targetLockLastTapWas(action,x,y,now=inputNow(),maxAge=140){const rec=specialControlState().lastTargetTapAction;if(!rec||rec.action!==action)return false;const age=Math.max(0,(Number(now)||0)-(Number(rec.at)||0));return age<=Math.max(0,Number(maxAge)||0)&&Math.abs((Number(rec.x)||0)-(Number(x)||0))<=2&&Math.abs((Number(rec.y)||0)-(Number(y)||0))<=2;}
function armTargetLockFireDeadline(now=inputNow()){const s=specialControlState();if(!targetLockTargetValid(s.lockedTarget)){s.targetSelectedAt=0;s.targetFireDeadlineAt=0;return 0;}const stamp=Number(now)||inputNow(),delay=Math.max(0,Number(CFG.targetSelectionFireTimeoutMs)||5000);s.targetSelectedAt=stamp;s.targetFireDeadlineAt=stamp+delay;return s.targetFireDeadlineAt;}
