function targetLockRoots(target){
  if(!target||!target.ref)return [];
  const ref=target.ref,out=[];
  if(target.kind==='environment'){
    if(ref.node)out.push(ref.node);for(const node of ref.nodes||[])if(node&&!out.includes(node))out.push(node);
  }else if(ref.group)out.push(ref.group);
  return out.filter(Boolean);
}
function targetLockTargetValid(target){
  if(!target||!target.ref)return false;
  const ref=target.ref;
  if(target.kind==='environment'){
    if(ref.destroyed||!G.environmentDestructibles||G.environmentDestructibles.get(String(ref.id||''))!==ref)return false;
    if(G.sectorStreamer&&!G.sectorStreamer.isActive(Number(ref.sectorIndex)))return false;
    return targetLockRoots(target).some(targetLockObjectVisible);
  }
  const w=ref.world;if(!w||!Number.isFinite(w.x)||!Number.isFinite(w.z)||!ref.group)return false;
  if(target.kind==='enemy')return !ref.dead&&ref.hp>0&&G.enemies.includes(ref)&&(!G.sectorStreamer||G.sectorStreamer.isActive(WorldSpace.sectorIndexAtZ(w.z)));
  if(target.kind==='fortress')return ref===G.fortress&&['dormant','defenders','boss','core'].includes(ref.state)&&(ref.state!=='core'||ref.coreHP>0)&&(!G.sectorStreamer||G.sectorStreamer.isActive(ref.sectorIndex));
  return false;
}
function targetLockWorld(target){
  if(!targetLockTargetValid(target))return null;const ref=target.ref;
  if(target.kind==='environment')return {x:Number(ref.x)||0,z:Number(ref.z)||0};
  const w=ref.world;return w&&Number.isFinite(Number(w.x))&&Number.isFinite(Number(w.z))?{x:Number(w.x),z:Number(w.z)}:null;
}
function targetLockLabel(target){
  if(!target||!target.ref)return 'TARGET';const ref=target.ref;
  if(target.kind==='environment')return String(ref.kind||'OBJECT').replace(/_/g,' ').toUpperCase();
  if(target.kind==='fortress')return (ref.state==='core'?'FORTRESS CORE ':'FORTRESS ')+String(ref.serial||ref.id||'');
  if(ref.boss)return 'ENEMY TANK · FORTRESS COMMANDER';if(ref.isZombie)return 'ZOMBIE '+String(ref.testOrdinal||String(ref.id||'').split(':').pop()).toUpperCase();return 'ENEMY '+String(ref.testOrdinal||String(ref.id||'').split(':').pop()).toUpperCase();
}
function targetLockCandidates(){
  const out=[];
  for(const e of G.enemies){if(!e||e.dead||!e.group||e.hp<=0)continue;const t={kind:'enemy',id:e.id,ref:e};if(targetLockTargetValid(t))out.push(t);}
  const f=G.fortress;if(f){const t={kind:'fortress',id:f.id,ref:f};if(targetLockTargetValid(t))out.push(t);}
  if(G.environmentDestructibles)for(const rec of G.environmentDestructibles.values()){if(!rec||rec.destroyed)continue;const t={kind:'environment',id:rec.id,ref:rec};if(targetLockTargetValid(t))out.push(t);}
  return out;
}



function targetLockRaycastCandidateAtScreen(x,y,candidates){
  const r=targetLockCanvasRect();
  if(!r||!G.raycaster||!Number.isFinite(x)||!Number.isFinite(y)||!pointInRect(r,x,y))return null;
  const list=Array.isArray(candidates)?candidates:targetLockCandidates(),roots=[],byRoot=new Map();
  for(const t of list)if(targetLockTargetValid(t))for(const root of targetLockRoots(t))if(targetLockObjectVisible(root)&&!byRoot.has(root)){roots.push(root);byRoot.set(root,t);}
  if(!roots.length)return null;
  try{
    if(G.scene&&G.scene.updateMatrixWorld)G.scene.updateMatrixWorld(true);if(G.camera.updateMatrixWorld)G.camera.updateMatrixWorld(true);for(const root of roots)if(root.updateMatrixWorld)root.updateMatrixWorld(true);
    G.raycaster.setFromCamera({x:(x-r.left)/r.width*2-1,y:1-(y-r.top)/r.height*2},G.camera);
    const hits=G.raycaster.intersectObjects(roots,true)||[];
    for(const hit of hits){if(!hit||!targetLockObjectVisible(hit.object))continue;for(let node=hit.object;node;node=node.parent){const target=byRoot.get(node);if(target)return target;}}
  }catch(error){if(localTargetLockTestRangeEnabled())console.warn('[Frontline1944] Target selection raycast failed',error);}
  return null;
}



