function precisionTurretStep(current,target,dt,scoped=scopeModeActive()){current=wrapPi(Number(current)||0);target=wrapPi(Number(target)||0);dt=clamp(Number(dt)||0,0,.05);const error=Math.abs(wrapPi(target-current));if(error<=1e-8||dt<=0)return error<=1e-8?target:current;const band=scoped?R4_AIM.scopePrecisionBand:R4_AIM.precisionBand,minRate=scoped?R4_AIM.turretScopeMinRate:R4_AIM.turretMinRate,maxRate=scoped?R4_AIM.turretScopeMaxRate:CFG.turretTurnRate,u=clamp(error/Math.max(.001,band),0,1),smooth=u*u*(3-2*u),rate=minRate+(maxRate-minRate)*smooth;return wrapPi(rotateToward(current,target,Math.min(error,rate*dt)));}function mobileAimStrength(aim){const mag=clamp(Math.hypot(Number(aim&&aim.x)||0,Number(aim&&aim.y)||0),0,1),dead=R5_AIM.mobileDeadZone;if(mag<=dead)return 0;const u=clamp((mag-dead)/Math.max(.001,1-dead),0,1);return Math.pow(u,R5_AIM.mobileResponseExponent);}function turretMotionStep(current,target,velocity,dt,scoped=false,inputStrength=1){current=wrapPi(Number(current)||0);target=wrapPi(Number(target)||0);velocity=Number.isFinite(Number(velocity))?Number(velocity):0;dt=clamp(Number(dt)||0,0,.05);const strength=clamp(Number(inputStrength)||0,0,1),error=wrapPi(target-current),absError=Math.abs(error),maxRate=scoped?R5_AIM.turretScopeMaxRate:R5_AIM.turretMaxRate,accel=scoped?R5_AIM.turretScopeAcceleration:R5_AIM.turretAcceleration,decel=scoped?R5_AIM.turretScopeDeceleration:R5_AIM.turretDeceleration;if(dt<=0)return {heading:current,velocity};let desired=0;if(strength>0&&absError>R5_AIM.turretHeadingEpsilon){const brakingRate=Math.sqrt(Math.max(0,2*decel*absError));desired=Math.sign(error)*Math.min(maxRate*strength,brakingRate);}const sameDirection=Math.abs(velocity)<=R5_AIM.turretStopEpsilon||Math.sign(velocity)===Math.sign(desired),speeding=sameDirection&&Math.abs(desired)>Math.abs(velocity),nextVelocity=approach(velocity,desired,(speeding?accel:decel)*dt);let heading=wrapPi(current+nextVelocity*dt),outVelocity=Math.abs(nextVelocity)<=R5_AIM.turretStopEpsilon&&Math.abs(desired)<=R5_AIM.turretStopEpsilon?0:nextVelocity;if(strength>0&&absError<=R5_AIM.turretHeadingEpsilon){heading=target;outVelocity=0;}else if(strength>0&&Math.sign(nextVelocity)===Math.sign(error)&&Math.abs(nextVelocity*dt)>=absError){heading=target;outVelocity=0;}return {heading,velocity:outVelocity};}





























