 bodies:Object.freeze([0x9bd8ed,0xb6e0a3,0xffd47a,0xf29c89]),
 ruinBodies:Object.freeze([0xa2c7c8,0xb4cba4,0xd4bd8e,0xca9489]),
 roof:0xd9654f,trim:0xfff2c2,window:0x4fa5c6,door:0xa66d43,industrialRoof:0x708b9a,
