function projectedShotSolution(t=G.player){if(!t||!G.collision)return null;const ray=r4CannonWorldRay(t),o=ray.origin,d=ray.direction,maxDistance=tankCannonRangeWorld(t),step=.75,radius=R4_AIM.projectileRadius,ignoreOwner=t.playerId||'';let last={x:o.x+d.x*.2,y:o.y+d.y*.2,z:o.z+d.z*.2,distance:.2,kind:'range',target:null};for(let distance=.2;;distance+=step){const actual=Math.min(distance,maxDistance),x=o.x+d.x*actual,y=o.y+d.y*actual,z=o.z+d.z*actual;last={x,y,z,distance:actual,kind:'range',target:null};if(y<=.08)return {...last,y:.08,kind:'terrain'};for(const e of G.enemies||[]){if(e.dead||!e.group)continue;const dx=x-e.world.x,dz=z-e.world.z,rr=radius+(Number(e.radius)||0),targetY=e.boss?2.6:2.2,vertical=e.boss?3.4:2.25;if(dx*dx+dz*dz<rr*rr&&Math.abs(y-targetY)<=vertical)return {...last,kind:'enemy',target:e};}const f=G.fortress;if(f&&f.state==='core'){const dx=x-f.world.x,dz=z-f.world.z;if(dx*dx+dz*dz<11&&Math.abs(y-3.2)<=4.8)return {...last,kind:'fortress_core',target:f};}if(y<=R6C_AIM.solidHeightGate){const solid=G.collision.hitSolidOnly(x,z,radius,ignoreOwner);if(solid)return {...last,kind:'solid',target:solid};}if(actual>=maxDistance)break;}return last;}














