  constructor(entity,collision,terrain){this.entity=entity;this.collision=collision;this.terrain=terrain;this.x=Number(entity.world.x)||0;this.z=Number(entity.world.z)||0;this.heading=wrapPi(Number(entity.hullRotation)||0);this.turretHeading=wrapPi(Number(entity.turretRotation)||this.heading);this.turretTargetHeading=this.turretHeading;this.turretAngularVelocity=0;this.barrelPitch=clampBarrelPitch(entity.barrelPitch);this.barrelTargetPitch=this.barrelPitch;this.barrelPitchVelocity=0;this.speed=Number(entity.speed)||0;this.lastMotion={dx:0,dz:0,longitudinalVelocity:0,lateralVelocity:0,blocked:false,heading:this.heading};this.syncEntity();}





























