function driveDirectionFromVector(x,y,active=true,deadZone=.22){if(!active)return '';x=Number(x)||0;y=Number(y)||0;const sx=Math.abs(x)>=deadZone?(x<0?'left':'right'):'',sy=Math.abs(y)>=deadZone?(y<0?'forward':'backward'):'';return sy&&sx?sy+'-'+sx:(sy||sx);}














function syncDriveDirectionUI(x=G.joy&&G.joy.x,y=G.joy&&G.joy.y,active=!!(G.joy&&G.joy.active)){const dir=driveDirectionFromVector(x,y,active),stick=$('#fl44-stick');if(!stick)return dir;if(!stick.dataset)stick.dataset={};stick.dataset.direction=dir;const lights=typeof stick.querySelectorAll==='function'?stick.querySelectorAll('.fl44-drive-light[data-dir]'):[];for(const light of lights){const on=String(light.dataset&&light.dataset.dir||'')===dir;if(light.classList)light.classList.toggle('is-active',on);}return dir;}





























