  clearDriveHold(g=this.driveGesture){if(g&&g.holdTimer!=null)clearTimeout(g.holdTimer);if(g)g.holdTimer=null;}














  activateDriveReposition(g=this.driveGesture){if(!g||this.driveGesture!==g||this.rolePointers.drive!==g.id||!g.repositionEligible||g.intent==='drive'||g.repositioning||g.maxMove>CFG.mobileDriveHoldMoveTolerancePx)return false;this.clearDriveHold(g);g.intent='reposition';g.repositioning=true;this.driveState.x=0;this.driveState.y=0;this.driveState.active=true;this.driveState.lastEventAt=inputNow();if(this.driveKnob&&this.driveKnob.style)this.driveKnob.style.transform='translate(0px,0px)';syncDriveDirectionUI(0,0,false);if(this.driveEl&&this.driveEl.classList)this.driveEl.classList.add('repositioning');this.onDiagnostic(this.snapshot());return true;}














  startDriveGesture(id,x,y,transport,repositionEligible=true){const startedAt=inputNow(),r=this.gestureRects.drive||this.rect('drive'),c=r?rectCenter(r):{x:Number(x)||0,y:Number(y)||0},px=Number(x)||0,py=Number(y)||0,neutralRadius=Math.max(16,Math.min(Number(r&&r.width)||96,Number(r&&r.height)||96)*.28),canReposition=!!repositionEligible&&Math.hypot(px-c.x,py-c.y)<=neutralRadius,g={id,startX:px,startY:py,lastX:px,lastY:py,baseX:c.x,baseY:c.y,dragOffsetX:c.x-px,dragOffsetY:c.y-py,startedAt,maxMove:0,transport,intent:canReposition?'pending':'drive',repositionEligible:canReposition,repositioning:false,holdTimer:null};if(g.repositionEligible)g.holdTimer=setTimeout(()=>this.activateDriveReposition(g),CFG.mobileDriveRepositionHoldMs);this.driveGesture=g;G.lastControlInputAt=startedAt;return g;}














  moveDriveGesture(id,x,y,transport){const g=this.driveGesture;if(!g||g.id!==id)return this.applyStick('drive',x,y,transport);const nx=Number(x)||0,ny=Number(y)||0,move=Math.hypot(nx-g.startX,ny-g.startY),elapsed=inputNow()-g.startedAt;g.lastX=nx;g.lastY=ny;g.maxMove=Math.max(g.maxMove,move);if(g.intent==='pending'){if(g.repositionEligible&&elapsed>=CFG.mobileDriveRepositionHoldMs&&g.maxMove<=CFG.mobileDriveHoldMoveTolerancePx)this.activateDriveReposition(g);else if(move>CFG.mobileDriveHoldMoveTolerancePx){g.intent='drive';this.clearDriveHold(g);}}if(g.repositioning){const next=findSafeDriveRect(this.root,this.driveEl,this.aimEl,this.fireEl,nx+g.dragOffsetX,ny+g.dragOffsetY);if(next){const actual=applyDriveRect(this.driveEl,next)||next;this.gestureRects.drive=actual;const c=rectCenter(actual);g.baseX=c.x;g.baseY=c.y;}this.driveState.x=0;this.driveState.y=0;this.driveState.active=true;this.driveState.transport=transport;this.driveState.lastTransport=transport;this.driveState.lastEventAt=inputNow();syncDriveDirectionUI(0,0,false);G.lastControlInputAt=this.driveState.lastEventAt;return {x:0,y:0,dx:0,dy:0};}return this.applyStick('drive',x,y,transport);}














  finishDriveGesture(id,cancelled=false){const g=this.driveGesture;if(!g||g.id!==id)return null;this.clearDriveHold(g);if(g.repositioning&&!cancelled)saveDrivePositionPreference(this.root,this.driveEl,this.aimEl,this.fireEl,this.storage);if(this.driveEl&&this.driveEl.classList)this.driveEl.classList.remove('repositioning');this.driveGesture=null;return g;}














