  startMgGesture(id,x,y,transport){const startedAt=inputNow(),r=this.gestureRects.mg||this.rect('mg'),c=r?rectCenter(r):{x:Number(x)||0,y:Number(y)||0},px=Number(x)||0,py=Number(y)||0,g={id,startX:px,startY:py,lastX:px,lastY:py,startedAt,maxMove:0,dragged:false,repositioning:false,firing:true,dragOffsetX:c.x-px,dragOffsetY:c.y-py,transport};this.mgGesture=g;this.onMgChange(true);if(this.mgEl&&this.mgEl.classList)this.mgEl.classList.add('on');G.lastControlInputAt=startedAt;return g;}
  moveMgGesture(id,x,y){const g=this.mgGesture;if(!g||g.id!==id)return null;g.lastX=Number(x)||0;g.lastY=Number(y)||0;g.maxMove=Math.max(g.maxMove,Math.hypot(g.lastX-g.startX,g.lastY-g.startY));if(g.maxMove>=CFG.mobileMgDragThresholdPx)g.dragged=true;const elapsed=inputNow()-g.startedAt;if(g.dragged&&elapsed>=CFG.mobileMgRepositionHoldMs){if(!g.repositioning){g.repositioning=true;if(g.firing){g.firing=false;this.onMgChange(false);}if(this.mgEl&&this.mgEl.classList){this.mgEl.classList.remove('on');this.mgEl.classList.add('repositioning');}}const r=findSafeMgRect(this.root,this.driveEl,this.aimEl,this.fireEl,this.mgEl,g.lastX+g.dragOffsetX,g.lastY+g.dragOffsetY);if(r){const actual=applyMgRect(this.mgEl,r);this.gestureRects.mg=actual||r;}}return g;}
