  const reset=()=>{G.keys.clear();G.desktopFireQueued=false;G.mobileFirePulseCount=0;G.lastDesktopAimAt=0;if(G.mobileRouter)G.mobileRouter.cancelAll();else{resetStickState(G.joy,$('.fl44-knob'));resetStickState(G.aim,$('.fl44-aim-knob'));G.firing=false;G.mgFiring=false;const fire=$('#fl44-fire'),mg=$('#fl44-mg');if(fire)fire.classList.remove('on');if(mg)mg.classList.remove('on');}};listen(window,'blur',reset);listen(document,'visibilitychange',()=>{if(document.hidden)reset();refreshFrontlineViewport();});














