function bindCanvasAim(){
  if(!G.canvas)return;
  listen(G.canvas,'pointermove',e=>{if(!G.viewportSuspended&&shouldAcceptDesktopAimEvent(e)){clearMobileAimLatch();noteDesktopAimInput();const p=pointerAimFromEvent(e);if(p)G.pointerAim=p;}});
  listen(G.canvas,'pointerleave',e=>{if(String(e.pointerType||'')==='mouse'&&!hasRecentTouchLikeInput())G.pointerAim=null;});
  listen(G.canvas,'pointerdown',e=>{if(!G.viewportSuspended&&e.button===0&&shouldAcceptDesktopAimEvent(e)){
    if(selectTargetLockAtScreen(e.clientX,e.clientY,false,e.target)){G.lastControlInputAt=inputNow();return;}
    clearMobileAimLatch();noteDesktopAimInput();const p=pointerAimFromEvent(e);if(p)G.pointerAim=p;G.desktopFireQueued=true;G.lastControlInputAt=inputNow();
  }});
}




