function r14TitanPlacement(){
  const current=G.sectorStreamer?Number(G.sectorStreamer.currentIndex)||0:WorldSpace.sectorIndexAtZ(G.player&&G.player.world?G.player.world.z:0),m=r12Mission();
  let sector=m?(Number(m.baseSector)||0)+5:current+2;
  if(sector<current-1){sector=current+2;for(let i=current+2;i<=current+10;i++){const off=m?i-(Number(m.baseSector)||0):-1;if(off===5||visualIdFor(i)===7){sector=i;break;}}}
  const centerZ=WorldSpace.sectorCenterZ(sector);return {sectorIndex:sector,x:-48,z:centerZ+20,centerZ};
}
