  r14TitanAddPart(root,'box',0x7f4358,34,22,22,0,74,1);r14TitanAddPart(root,'box',0x78a95d,38,70,24,0,116,0);r14TitanAddPart(root,'box',0xb64d5f,50,10,25,0,146,0);
  r14TitanAddPart(leftArm,'box',0x6e9b59,11,72,12,-26,112,0);r14TitanAddPart(rightArm,'box',0x6e9b59,11,72,12,26,112,0);
