  if(!t||t!==G.titan||t.dead||!r14PlayerDamageSource(projectile))return false;const mg=String(projectile.weaponId||'').startsWith('machine_gun_'),scale=mg?R14_TITAN_SYSTEM.mgDamageScale:R14_TITAN_SYSTEM.cannonDamageScale,damage=Math.max(0,Number(rawDamage)||0)*scale;if(damage<=0)return false;
  r14ProvokeTitan(t);const before=t.hp,actual=Math.min(before,damage);t.hp=Math.max(0,before-actual);const killed=t.hp<=0;recordCombatDamage({sourceId:projectile.ownerId,targetId:t.id,targetType:'ZOMBIE',actualDamage:actual,killed,kind:mg?'titan_mg':'titan_cannon'});
