  if(!t||t.dead||t.stompResolved||!t.stompImpact)return false;t.stompResolved=true;if(t.marker)t.marker.visible=false;burst(t.stompImpact,0xd5b46c,10);const hit=G.player&&r14StompHitsPosition(t.stompImpact,G.player.world);if(hit)r14InstantPlayerDeath();t.state='STOMP_RECOVER';t.phaseTime=0;t.stateTime=R14_TITAN_SYSTEM.stompRecoverSeconds;t.stompCooldown=R14_TITAN_SYSTEM.stompCooldownSeconds;return hit;
