targetLockDetails=function(target){if(target&&target.ref&&target.ref.isTitan){const t=target.ref,health='HP '+Math.max(0,Math.ceil(t.hp))+'/'+Math.ceil(t.maxHp),status=t.hostile?'PROVOKED · KEEP DISTANCE':'PASSIVE · ATTACK TO PROVOKE';return health+' · '+status;}return _r14TargetLockDetails(target);};
tickProjectilePool=function(pool,dt,isPlayer){const result=_r14TickProjectilePool(pool,dt,isPlayer);if(isPlayer)r14ResolveTitanProjectileHits(pool);return result;};
