function r15EnsureMissionCarrierNear(state=G.zombieCrowd){if(!state||!G.player||!G.word)return;const needed=String(G.word.en&&G.word.en[G.pos]||'').toUpperCase();if(!needed)return;let nearestCorrect=null,nearestCorrectD=Infinity,nearestAny=null,nearestAnyD=Infinity;for(const rec of state.carriers){if(rec.deadUntil)continue;const dx=rec.world.x-G.player.world.x,dz=rec.world.z-G.player.world.z,d=dx*dx+dz*dz;if(d<nearestAnyD){nearestAny=rec;nearestAnyD=d;}if(rec.letter===needed&&d<nearestCorrectD){nearestCorrect=rec;nearestCorrectD=d;}}if(nearestCorrect&&nearestCorrectD<=R15_SYSTEM.missionCarrierAssistRadius*R15_SYSTEM.missionCarrierAssistRadius)return;if(!nearestAny)return;if(nearestAnyD>R15_SYSTEM.missionCarrierAssistRadius*R15_SYSTEM.missionCarrierAssistRadius){const c=nearestAny.cluster;if(!r15ClusterHasActive(c,state)){c.sector=WorldSpace.sectorIndexAtZ(G.player.world.z);c.x=clamp(G.player.world.x+(r15Hash(c.index*307)-.5)*54,-CFG.sectorWidth*.36,CFG.sectorWidth*.36);c.localZ=(G.player.world.z-WorldSpace.sectorCenterZ(c.sector))-68;for(const rec of c.records)r15PlaceRecord(rec,true);}}nearestAny.letter=needed;const active=state.activeByRecord.get(nearestAny.id);if(active)r15SetCarrierBadge(active,needed);}
