function r15UpdateFullActors(state=G.zombieCrowd){if(!state||!G.player)return;for(const [id,e] of [...state.activeByRecord])if(!e||!e.group||!G.enemies.includes(e)){if(e)r15ActorRelease(e,state);else state.activeByRecord.delete(id);}const cap=G.lowFx?R15_SYSTEM.lowFxFullActorCap:R15_SYSTEM.fullActorCap,r2=R15_SYSTEM.fullActorRadius*R15_SYSTEM.fullActorRadius,candidates=[];for(const rec of state.records){if(rec.deadUntil)continue;const dx=rec.world.x-G.player.world.x,dz=rec.world.z-G.player.world.z,d2=dx*dx+dz*dz;if(d2<=r2)candidates.push({rec,d2,priority:rec.letterCarrier&&rec.letter===String(G.word&&G.word.en&&G.word.en[G.pos]||'').toUpperCase()?0:rec.letterCarrier?1:2});}candidates.sort((a,b)=>a.priority-b.priority||a.d2-b.d2);const wanted=new Set(candidates.slice(0,cap).map(x=>x.rec.id));for(const [id,e] of [...state.activeByRecord])if(!wanted.has(id)&&!r17FlingActive(e))r15ActorRelease(e,state);for(const item of candidates){if(state.activeByRecord.size>=cap)break;if(!state.activeByRecord.has(item.rec.id))r15ActorAcquire(item.rec,state);}state.lastFullCount=state.activeByRecord.size;}
