const R17_SYSTEM=Object.freeze({id:'P2.1R17-e2e9bd',taskId:'VW-20260907-165548-e2e9bd',baselineId:'P2.1R16-e5aff4',presentation:R15_SYSTEM.presentation,turretSweepReach:8.15,turretSweepInnerRadius:1.55,turretSweepHalfWidth:.78,turretSweepMinAngle:.0045,turretSweepCooldownMs:480,turretSweepMaxHitsPerStep:1,baselineHorizontalLaunch:30,flingSpeedMultiplier:100,flingDistanceMultiplier:100,horizontalLaunch:80,verticalLaunch:8.8,flingGravity:24,flingHorizontalDrag:1.35,flingMaxSeconds:1.25,minimumDistanceRatio:.985});

function r17ApplyRuntimeIdentity(reason='r17'){if(!G.root)return null;G.root.dataset.runtimeVersion=R17_SYSTEM.id;G.root.dataset.patchTask=R17_SYSTEM.id;G.root.dataset.taskId=R17_SYSTEM.taskId;G.root.dataset.baselineTask=R17_SYSTEM.baselineId;G.root.dataset.presentationRevision=R17_SYSTEM.id;G.root.dataset.runtimeReason=reason;const el=$('#fl44-runtime');if(el){const delivery=frontlineDeliveryIdentity();el.textContent='RUNTIME: '+R17_SYSTEM.id;el.title='R17 gameplay revision | delivery handshake: '+String(delivery.runtimeId||CFG.runtimeVersion)+' | CSS: '+String(delivery.cssRuntimeId||delivery.cssAsset||'—');}return R17_SYSTEM.id;}

