function r17TurretSweepEligible(e){return !!(e&&e.isZombie&&e.crowdManaged&&!e.dead&&!e.isTitan&&e.world);}
function r17SweepContainsPoint(tankX,tankZ,previousHeading,currentHeading,x,z,radius=1){const dx=(Number(x)||0)-(Number(tankX)||0),dz=(Number(z)||0)-(Number(tankZ)||0),dist=Math.hypot(dx,dz),r=Math.max(.1,Number(radius)||1);if(dist<R17_SYSTEM.turretSweepInnerRadius-r*.35||dist>R17_SYSTEM.turretSweepReach+r)return false;const delta=wrapPi((Number(currentHeading)||0)-(Number(previousHeading)||0));if(Math.abs(delta)<R17_SYSTEM.turretSweepMinAngle)return false;const pointHeading=rotationFromForward(dx,dz),relative=wrapPi(pointHeading-(Number(previousHeading)||0)),pad=Math.asin(clamp((r+R17_SYSTEM.turretSweepHalfWidth)/Math.max(dist,r+R17_SYSTEM.turretSweepHalfWidth+.01),0,.88));return delta>0?relative>=-pad&&relative<=delta+pad:relative<=pad&&relative>=delta-pad;}
function r17LaunchVector(tankX,tankZ,zombieX,zombieZ,previousHeading,currentHeading){const delta=wrapPi((Number(currentHeading)||0)-(Number(previousHeading)||0)),mid=wrapPi((Number(previousHeading)||0)+delta*.5),sign=delta>=0?1:-1,dx=(Number(zombieX)||0)-(Number(tankX)||0),dz=(Number(zombieZ)||0)-(Number(tankZ)||0),L=Math.hypot(dx,dz)||1,outX=dx/L,outZ=dz/L,tanX=-Math.cos(mid)*sign,tanZ=Math.sin(mid)*sign,mixX=tanX*.84+outX*.58,mixZ=tanZ*.84+outZ*.58,mixL=Math.hypot(mixX,mixZ)||1,boost=R17_SYSTEM.horizontalLaunch*(1+Math.min(.35,Math.abs(delta)*2.3));return {x:mixX/mixL*boost,z:mixZ/mixL*boost,y:R17_SYSTEM.verticalLaunch};}
function r17OpenWorldFlingDuration(){const ballistic=R17_SYSTEM.flingGravity>0?2*R17_SYSTEM.verticalLaunch/R17_SYSTEM.flingGravity:R17_SYSTEM.flingMaxSeconds;return Math.min(R17_SYSTEM.flingMaxSeconds,Math.max(.18,ballistic));}
