function r17StartFling(e,velocity,now=inputNow()){if(!r17TurretSweepEligible(e)||!velocity)return false;const vx=Number(velocity.x)||0,vz=Number(velocity.z)||0,planarSpeed=Math.hypot(vx,vz),baselineSpeed=planarSpeed/R17_SYSTEM.flingSpeedMultiplier,targetDistance=r17OpenWorldFlingDistanceForSpeed(baselineSpeed)*R17_SYSTEM.flingDistanceMultiplier;e.r17Fling={active:true,vx,vz,vy:Number(velocity.y)||R17_SYSTEM.verticalLaunch,y:Math.max(0,Number(e.group&&e.group.position&&e.group.position.y)||0),startedAt:Number(now)||0,age:0,originX:Number(e.world.x)||0,originZ:Number(e.world.z)||0,travelled:0,targetDistance};if(e.crowdRecord)e.crowdRecord.r17SweepCooldownUntil=(Number(now)||0)+R17_SYSTEM.turretSweepCooldownMs;return true;}
function r17FinishFling(e){if(!e)return false;if(e.group){e.group.position.y=0;e.group.rotation.z=0;}e.r17Fling=null;return true;}
function r17TickFlingActor(e,dt,now=inputNow()){if(!r17FlingActive(e)||!e.world)return false;const f=e.r17Fling,h=clamp(Number(dt)||0,0,.05);f.age+=h;f.vy-=R17_SYSTEM.flingGravity*h;const k=R17_SYSTEM.flingHorizontalDrag,decay=k>1e-9?Math.exp(-k*h):1,travelFactor=k>1e-9?(1-decay)/k:h,dx=f.vx*travelFactor,dz=f.vz*travelFactor;e.world.x+=dx;e.world.z+=dz;f.travelled+=Math.hypot(dx,dz);f.vx*=decay;f.vz*=decay;f.y=Math.max(0,f.y+f.vy*h);if(e.group){e.group.position.set(e.world.x,f.y,e.world.z);e.group.rotation.z=clamp(-f.vx*.00018,-.42,.42);}if(e.crowdRecord){e.crowdRecord.world.x=e.world.x;e.crowdRecord.world.z=e.world.z;}const landed=f.y<=0&&f.age>.18,reachedDistance=f.targetDistance<=0||f.travelled>=f.targetDistance*R17_SYSTEM.minimumDistanceRatio;if((landed&&reachedDistance)||f.age>=R17_SYSTEM.flingMaxSeconds){r17FinishFling(e);return false;}return true;}
function r17ResolveTurretSweep(previousHeading,currentHeading,dt,now=inputNow()){if(!G.player||!G.zombieCrowd)return 0;const lastAim=manualAimLastInputAt(),manual=!!(G.aim&&G.aim.active)||(Number(now)-Number(lastAim||0)<=220);if(!manual)return 0;const pose=authoritativeTankPose(G.player),delta=wrapPi((Number(currentHeading)||0)-(Number(previousHeading)||0));if(Math.abs(delta)<R17_SYSTEM.turretSweepMinAngle)return 0;let hits=0;for(const e of G.zombieCrowd.activeByRecord.values()){if(!r17TurretSweepEligible(e))continue;const rec=e.crowdRecord,cooldown=Number(rec&&rec.r17SweepCooldownUntil)||0;if(Number(now)<cooldown)continue;if(!r17SweepContainsPoint(pose.x,pose.z,previousHeading,currentHeading,e.world.x,e.world.z,e.radius))continue;const launch=r17LaunchVector(pose.x,pose.z,e.world.x,e.world.z,previousHeading,currentHeading);if(r17StartFling(e,launch,now)){hits++;if(hits>=R17_SYSTEM.turretSweepMaxHitsPerStep)break;}}return hits;}

