function r17RemoveLegacyLeftWeapons(){let removed=0;for(const id of ['fl44-'+'fire-left','fl44-'+'mg-left']){const el=$('#'+id);if(el&&el.parentNode){el.parentNode.removeChild(el);removed++;}}const legacy=G.r16LeftControls;if(legacy&&legacy.pointers&&legacy.pointers.values)for(const gesture of legacy.pointers.values())if(gesture&&gesture.timer)clearTimeout(gesture.timer);if(Object.prototype.hasOwnProperty.call(G,'r16LeftControls'))delete G.r16LeftControls;try{const storage=fireStorage(),data=readFirePositionStore(storage);let dirty=false;for(const key of Object.keys(data||{}))if(key.startsWith('r16:'+('left'+'Fire')+':')||key.startsWith('r16:'+('left'+'Mg')+':')){delete data[key];dirty=true;}if(dirty)writeFirePositionStore(data,storage);}catch(_){/* persistence cleanup must never block gameplay */}return removed;}

